function resourceCacher(url, storageKey, name, dateDelta, type) {
    let database
    async function load() {
        const raw_data = (
            await externalFetchRetry({
                url: url,
                responseType: type,
            })
        ).response
        if (!raw_data) {
            throw `${name} not downloaded`
        }
        database = raw_data
        console.log(`${name} database updated`)
        await GM.setValue(
            storageKey,
            JSON.stringify({
                raw_data: raw_data,
                cacheTime: new Date(),
            }),
        )
    }
    return {
        get: () => database,
        init: async function () {
            if (database) return
            const cache = await GM.getValue(storageKey, "")
            if (database) return
            if (cache) {
                console.log(`${name} cached`)
                const json = JSON.parse(cache)
                const cacheTime = new Date(json["cacheTime"])
                const timeLater = new Date(cacheTime.getTime() + dateDelta)
                if (timeLater < new Date()) {
                    console.log("but cache outdated")
                    setTimeout(load, 0)
                }
                database = JSON.parse(cache)["raw_data"]
                return
            }
            console.log(`loading ${name}`)
            try {
                await load()
            } catch (e) {
                console.log(`loading ${name} failed`, e)
            }
        },
    }
}

function getOverpassApiInterpreterEndpoint(query = "") {
    let apiURL = overpass_server.apiUrl
    const customServer = JSON.parse(GM_config.get("CustomOverpassInstance") ?? "")
    if (osm_server === prod_server && customServer?.URL) {
        if (
            query.includes("[date:") ||
            query.includes("[adiff:") ||
            query.includes("[diff:") ||
            query.includes("timeline(") ||
            query.includes("retro(")
        ) {
            if (customServer["attic-data"]) {
                apiURL = customServer.URL
            }
        }
        apiURL = customServer.URL
    }
    console.log("Used Overpass API", apiURL + "/interpreter")
    return apiURL + "/interpreter"
}

/**
 * @param {string} query
 * @param {"json"|"xml"} responseType
 * @param {boolean} withRetry
 * @return {Promise<Tampermonkey.Response<unknown>>}
 */
async function overpassRequest(query, responseType = "json", withRetry = true) {
    console.time("download overpass data " + query)
    console.log("overpass request", query)
    console.count("kek")
    const rateLimiter = {
        key: "overpass",
        minDelay: 1000,
    }
    const url = getOverpassApiInterpreterEndpoint()
    const fetchImpl = withRetry ? externalFetchRetry : externalFetch
    try {
        if (overpass_server.referer) {
            return await fetchImpl({
                method: "POST",
                url: url,
                data: query,
                headers: {
                    Referer: overpass_server.referer,
                    Origin: overpass_server.origin,
                },
                responseType: responseType,
                rateLimiter: rateLimiter,
            })
        }
        return await fetchImpl({
            method: "POST",
            url: url,
            data: query,
            responseType: responseType,
            rateLimiter: rateLimiter,
        })
    } finally {
        console.timeEnd("download overpass data " + query)
    }
}

