function makeVespucciMultiUrl(nodes, ways, relations) {
    return (
        "josm:/load_object?objects=" +
        [nodes.map(i => "n" + i).join(","), ways.map(i => "w" + i).join(","), relations.map(i => "r" + i).join(",")]
            .join(",")
            .replace(/,,/, ",")
            .replace(/,$/, "")
            .replace(/^,/, "")
    )
}

function actionOpenInVespucci() {
    const match = location.pathname.match(/(node|way|relation)\/(\d+)(\/?$|\/history\/?$)/)
    if (match) {
        openNewTab(`josm:/load_object?objects=${match[1][0]}${match[2]}`)
        return
    }
    if (jsonLayer) {
        const { nodes, ways, relations } = splitJsonLayerByOsmType(jsonLayer)
        openNewTab(makeVespucciMultiUrl(nodes, ways, relations))
        return
    }
    console.warn("nothing to open")
}

function actionOpenOwnHistoryPage() {
    addCompactSidebarStyle()
    const targetURL = document.querySelector('.dropdown-item[href^="/user/"]').getAttribute("href") + "/history"
    if (targetURL !== location.pathname) {
        try {
            getWindow().OSM.router.route(targetURL)
        } catch {
            location.pathname = targetURL
        }
    }
}

function actionOpenRelevantHistoryPage() {
    if (isObjectPage()) {
        if (/^\/(node|way|relation)\/\d+\/?$/.test(location.pathname)) {
            getWindow().OSM.router.route(location.pathname + "/history")
        } else if (/^\/(node|way|relation)\/\d+\/history\/\d+\/?$/.test(location.pathname)) {
            const historyPath = location.pathname.match(/(\/(node|way|relation)\/\d+\/history)\/\d+/)[1]
            getWindow().OSM.router.route(historyPath)
        }
    } else if (isHomeOrNotePage()) {
        addCompactSidebarStyle()
        document.querySelector('.nav-link[href*="/history"]')?.click()
    } else if (location.pathname.includes("/user/")) {
        document.querySelector('a[href^="/user/"][href$="/history"]')?.click()
    }
}

